<?php if (!empty($view['site']['site_description'])): ?><div class="pg-profile-bio"><p class="pg-bio-text"><?php echo snap_escape_html($view['site']['site_description']); ?></p></div><?php endif; ?></section><div class="pg-divider"></div><?php if (!empty($view['site']['skin_presentation']['discover']['visible'])): ?><section class="pg-discover" aria-label="Discover"><h2 class="pg-discover-heading">Discover</h2><?php echo snap_render_html(snap_render_component('navigation',['items'=>$view['response']['navigation'] ?? []])); ?></section><?php endif; ?>
