<div class="pg-post-image-wrap"><?php if (!empty($view['response']['item']['img_file']) || !empty($view['response']['item']['featured_image_path'])): ?><?php echo snap_render_html(snap_render_component('image',['url'=>$view['response']['item']['img_file'] ?? $view['response']['item']['featured_image_path'],'alt'=>$view['response']['item']['img_alt'] ?? $view['response']['item']['img_title'] ?? '','class'=>'pg-post-image u-photo'])); ?><?php endif; ?></div>
